const results = [];
const binaryData = $binary;
// Obtenemos el campo del formulario (puede ser un Array o un Objeto)
let rawFiles = items[0].json["Seleccionar archivos"];

// Si es un objeto solo, lo metemos adentro de un array para que el loop funcione igual
if (!Array.isArray(rawFiles)) {
  rawFiles = [rawFiles];
}

// Recorremos la lista (que ahora siempre es una lista)
rawFiles.forEach((file, index) => {
  // n8n nombra al primero "Seleccionar_archivos" y a los siguientes "_1", "_2"...
  // O a veces "_0", "_1". Para estar seguros, buscamos dinámicamente:
  const binaryKey = index === 0 && binaryData["Seleccionar_archivos"] 
    ? "Seleccionar_archivos" 
    : `Seleccionar_archivos_${index}`;

  // Si no lo encuentra con esa lógica, buscamos la key que contenga el índice
  const actualKey = binaryData[binaryKey] ? binaryKey : Object.keys(binaryData).find(k => k.endsWith(`_${index}`)) || Object.keys(binaryData)[index];

  if (binaryData[actualKey]) {
    results.push({
      json: {
        filename: file.filename,
        mimetype: file.mimetype,
        size: file.size,
        index: index,
        total_files: rawFiles.length
      },
      binary: {
        file: binaryData[actualKey]
      }
    });
  }
});

return results;
